function enc(text:string,pwd:string){return btoa(unescape(encodeURIComponent(text.split("").reverse().join("")+"::"+pwd)));}
function dec(cipher:string,pwd:string){try{const raw=decodeURIComponent(escape(atob(cipher))); if(!raw.endsWith("::"+pwd)) return null; return raw.slice(0,-(pwd.length+2)).split("").reverse().join("");}catch{return null;}}
const initials=(n:string)=>n.split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase();
const now=()=>new Date().toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"});

