 const filteredPros=(()=>{ let list=pros.filter(p=>(proCategory==="tous"||p.category===proCategory)&&(!onlyOnline||p.online)&&(!proSearch||[p.name,p.role,p.company,p.specialty,p.location,catLabel(p.category)].join(" ").toLowerCase().includes(proSearch.toLowerCase())));
   if(proSort==="note") list=[...list].sort((a,b)=>parseFloat(b.rating)-parseFloat(a.rating)); if(proSort==="avis") list=[...list].sort((a,b)=>b.reviews-a.reviews); if(proSort==="prix") list=[...list].sort((a,b)=>priceNum(a)-priceNum(b)); if(proSort==="rapide") list=[...list].sort((a,b)=>(a.responseTime||"").localeCompare(b.responseTime||""));
   return list; })();
 const contactPro=(p:Pro)=>{ const existing=contacts.find(x=>x.name===p.name); if(existing){ setActiveId(existing.id); setContacts(prev=>prev.map(x=>x.id===existing.id?{...x,unread:0}:x)); return; } const nc:Contact={id:100+p.id,name:p.name,role:`${p.role} • ${p.company}`,color:p.color,online:p.online,vip:false,aiAllowed:false,last:`Bonjour, je suis ${p.name.split(" ")[0]} (${p.role}). Comment puis-je vous aider ?`,time:now(),unread:0}; setContacts(prev=>[nc,...prev]); setMsgs(prev=>({...prev,[nc.id]:[{id:1,from:"them",text:`Bonjour Alex 👋 Je suis ${p.name}, ${p.role} chez ${p.company}. Spécialité : ${p.specialty}. Décrivez-moi votre besoin, je réponds en ${p.responseTime||"~15 min"} !`,time:now()}]})); setActiveId(nc.id); setSelectedPro(null); showToast(`💬 Discussion ouverte avec ${p.name}`); };
