 const advanceHelp=(r:HelpReq)=>{ const flow=["En attente d'un pro","Pro contacté","✅ Pro a accepté — échange ouvert","En cours","Terminée ⭐"]; const next=flow[Math.min(flow.indexOf(r.status)+1<0?1:flow.indexOf(r.status)+1,flow.length-1)]||flow[1]; setHelpRequests(p=>p.map(x=>x.id===r.id?{...x,status:next}:x)); showToast(`📍 ${r.ticket} : ${next}`); };
